  "glossary": [
    {
      "term": "corridor care",
      "definition": "Treating or leaving patients in hospital corridors or non-clinical spaces because no proper beds or cubicles are available."
    },
    {
      "term": "four-hour standard",
      "definition": "NHS target that most emergency department patients should be admitted, transferred or discharged within four hours of arrival."
    },
    {
      "term": "ICB",
      "definition": "Integrated Care Board: the local organisation that plans and pays for NHS services in an area."
    },
    {
      "term": "criteria to reside",
      "definition": "Clinical rules used to decide whether a patient still needs an acute hospital bed or can be discharged."
    },
    {
      "term": "delayed discharge",
      "definition": "When a patient is medically ready to leave hospital but cannot because appropriate care or accommodation is not in place."
    },
    {
      "term": "category 2",
      "definition": "An ambulance performance category covering urgent but not immediately life-threatening calls, measured by response time."
    },
    {
      "term": "model ED",
      "definition": "A defined way of organising an emergency department to improve flow, safety and timeliness of care."
    }
  ]
